const cfg = $('Set config: categories & interests').first().json;
const CATALOG = {"ai":["https://huggingface.co/blog/feed.xml","https://the-decoder.com/feed/","https://venturebeat.com/category/ai/feed/","https://simonwillison.net/atom/everything/","https://openai.com/blog/rss.xml","https://deepmind.google/blog/rss.xml","https://bair.berkeley.edu/blog/feed.xml","https://jack-clark.net/feed/","https://hnrss.org/newest?q=AI+OR+LLM&points=100"],"tech":["https://www.theverge.com/rss/index.xml","https://techcrunch.com/feed/","https://arstechnica.com/feed/","https://www.wired.com/feed/rss","https://www.engadget.com/rss.xml","https://hnrss.org/frontpage","https://www.technologyreview.com/feed/","https://restofworld.org/feed/latest/"],"startups":["https://techcrunch.com/category/startups/feed/","https://news.crunchbase.com/feed/","https://www.saastr.com/feed/","https://tomtunguz.com/index.xml","https://andrewchen.com/feed/"],"jobs":["https://weworkremotely.com/remote-jobs.rss","https://hnrss.org/jobs","https://hnrss.org/whoishiring/jobs","https://remotive.com/remote-jobs/feed","https://jobicy.com/?feed=job_feed"],"dev":["https://dev.to/feed","https://css-tricks.com/feed/","https://martinfowler.com/feed.atom","https://stackoverflow.blog/feed/","https://github.blog/feed/","https://www.smashingmagazine.com/feed/","https://overreacted.io/rss.xml"],"product_design":["https://www.lennysnewsletter.com/feed","https://uxdesign.cc/feed","https://www.nngroup.com/feed/rss/","https://uxplanet.org/feed"],"security":["https://krebsonsecurity.com/feed/","https://www.bleepingcomputer.com/feed/","https://feeds.feedburner.com/TheHackersNews","https://www.schneier.com/feed/atom/","https://www.darkreading.com/rss.xml"],"business_finance":["https://feeds.a.dj.com/rss/RSSMarketsMain.xml","https://www.cnbc.com/id/1+1234567890/device/rss/rss.html","https://feeds.bloomberg.com/technology/news.rss","https://fortune.com/feed/"],"science":["https://www.sciencedaily.com/rss/all.xml","https://arstechnica.com/science/feed/","https://www.quantamagazine.org/feed/","https://phys.org/rss-feed/"],"marketing":["https://searchengineland.com/feed","https://moz.com/blog/feed","https://www.socialmediaexaminer.com/feed/","https://www.marketingdive.com/feeds/news/"],"world":["https://feeds.bbci.co.uk/news/rss.xml","https://www.aljazeera.com/xml/rss/all.xml","https://feeds.npr.org/1001/rss.xml","https://rss.nytimes.com/services/xml/rss/nyt/HomePage.xml"]};
const wanted = String(cfg.categories || '').toLowerCase().trim();
const cats = (!wanted || wanted === 'all')
  ? Object.keys(CATALOG)
  : wanted.split(',').map((s) => s.trim()).filter((c) => CATALOG[c]);
const feeds = [];
for (const c of cats) for (const url of (CATALOG[c] || [])) feeds.push({ feedUrl: url, category: c });
return feeds.map((f) => ({ json: f }));

const cfg = $('Set config: categories & interests').first().json;
const feedsIn = $('Expand selected feeds').all();
const perFeed = Number(cfg.perFeed) || 10;
const hours = Number(cfg.hoursBack) || 24;
const cutoff = Date.now() - hours * 3600 * 1000;
const maxItems = Number(cfg.maxItems) || 40;

const strip = (h) => String(h || '').replace(/<!\[CDATA\[|\]\]>/g, '').replace(/<[^>]+>/g, ' ').replace(/&[a-z#0-9]+;/g, ' ').replace(/\s+/g, ' ').trim();
const tag = (b, t) => { const m = new RegExp('<' + t + '[^>]*>([\\s\\S]*?)</' + t + '>', 'i').exec(b); return m ? m[1] : ''; };
function parse(xml) {
  const out = []; const re = /<(item|entry)[\s\S]*?<\/\1>/gi; let m;
  while ((m = re.exec(xml))) {
    const b = m[0];
    let link = strip(tag(b, 'link'));
    if (!link) { const h = /<link[^>]*href="([^"]+)"/i.exec(b); if (h) link = h[1]; }
    out.push({
      title: strip(tag(b, 'title')), link,
      snippet: strip(tag(b, 'description') || tag(b, 'summary') || tag(b, 'content')).slice(0, 400),
      date: strip(tag(b, 'pubDate') || tag(b, 'updated') || tag(b, 'published') || tag(b, 'dc:date')),
    });
  }
  return out;
}
// map each HTTP response back to the feed (and its category) that produced it
const catOf = (it, idx) => {
  let pi = it.pairedItem;
  let p = (typeof pi === 'number') ? pi : (Array.isArray(pi) ? (pi[0] || {}).item : (pi || {}).item);
  if (p === undefined || p === null) p = idx;
  return (feedsIn[p] && feedsIn[p].json.category) || 'general';
};

const seen = new Set(); const items = [];
const responses = $input.all();
for (let idx = 0; idx < responses.length; idx++) {
  const j = responses[idx].json || {};
  const xml = typeof j.data === 'string' ? j.data : (typeof j.body === 'string' ? j.body : (typeof responses[idx].json === 'string' ? responses[idx].json : ''));
  if (!xml) continue;
  const category = catOf(responses[idx], idx);
  for (const a of parse(xml).slice(0, perFeed)) {
    if (!a.title || !a.link) continue;
    const ts = Date.parse(a.date) || Date.now();
    if (ts < cutoff) continue;
    const key = a.link.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    items.push({ title: a.title, link: a.link, snippet: a.snippet, category, ts });
  }
}
items.sort((x, y) => y.ts - x.ts);
// balance the pool round-robin across categories so a high-volume tag (e.g. tech) does not crowd out others
const buckets = {};
for (const a of items) (buckets[a.category] = buckets[a.category] || []).push(a); // already recency-sorted
const catKeys = Object.keys(buckets);
const balanced = []; let added = true;
while (balanced.length < maxItems && added) {
  added = false;
  for (const c of catKeys) { if (buckets[c].length) { balanced.push(buckets[c].shift()); added = true; if (balanced.length >= maxItems) break; } }
}
const capped = balanced.map((a, i) => ({ i, title: a.title, link: a.link, snippet: a.snippet, category: a.category }));
return [{ json: { items: capped, count: capped.length } }];

const cfg = $('Set config: categories & interests').first().json;
const items = $json.items || [];
const schema = { type: 'object', additionalProperties: false, required: ['overview', 'picks'], properties: {
  overview: { type: 'string' },
  picks: { type: 'array', items: { type: 'object', additionalProperties: false,
    required: ['i', 'headline', 'why', 'category', 'importance'], properties: {
      i: { type: 'integer' }, headline: { type: 'string' }, why: { type: 'string' },
      category: { type: 'string' }, importance: { type: 'integer' } } } } } };
const system = 'You are a sharp editor building a personalised brief for ONE reader. Each article already has a category tag. Drop near-duplicates and low-signal noise, then pick the most relevant to the reader interests across ALL categories. For each pick: headline = a tight rewrite, why = one sentence on why it matters to this reader, category = keep the article tag, importance = 0-100. overview = a 2-sentence read of the day. Keep the mix of categories the reader selected; do not over-index on one. Be terse, no hype.';
const user = 'READER INTERESTS: ' + cfg.interests + '\n\nSelected categories present: ' + (items.length ? [...new Set(items.map((a) => a.category))].join(', ') : '') +
  '. Pick the top ' + (cfg.topN || 15) + ' overall.\n\nARTICLES (reference each by index i):\n' +
  items.map((a) => '[' + a.i + '] (' + a.category + ') ' + a.title + '\n' + a.snippet).join('\n\n');
return [{ json: { body: {
  model: cfg.model, max_tokens: 2500, system,
  messages: [{ role: 'user', content: user }],
  output_config: { format: { type: 'json_schema', schema } },
} } }];

const cfg = $('Set config: categories & interests').first().json;
const items = $('Parse & tag articles').first().json.items || [];
const labels = {"ai":"AI","tech":"Tech","startups":"Startups","jobs":"Jobs","dev":"Dev","product_design":"Product & Design","security":"Security","business_finance":"Business & Finance","science":"Science","marketing":"Marketing","world":"World"};
const top = Number(cfg.topN) || 15;
const blocks = ($json.content || []);
const text = (blocks.find((b) => b.type === 'text') || {}).text || '{"overview":"","picks":[]}';
let parsed = { overview: '', picks: [] };
try { parsed = JSON.parse(text); } catch (e) {}
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const picks = (parsed.picks || []).map((p) => ({ ...p, ...(items[p.i] || {}), category: p.category || (items[p.i] || {}).category }))
  .filter((p) => p.link).sort((a, b) => b.importance - a.importance).slice(0, top);
const groups = {};
for (const p of picks) (groups[p.category] = groups[p.category] || []).push(p);
let body = '';
for (const cat of Object.keys(groups)) {
  body += '<h3 style="margin:16px 0 6px;text-transform:uppercase;letter-spacing:.04em;color:#111">' + esc(labels[cat] || cat) + '</h3><ul style="padding-left:18px;margin:0">';
  for (const p of groups[cat]) body += '<li style="margin:8px 0"><a href="' + esc(p.link) + '" style="font-weight:700">' + esc(p.headline) + '</a> <span style="color:#999">· ' + p.importance + '</span><br><span style="color:#333">' + esc(p.why) + '</span></li>';
  body += '</ul>';
}
const html = '<h2 style="font-family:system-ui,Arial">Your morning brief</h2>' +
  (parsed.overview ? '<p style="color:#444;font-family:system-ui,Arial">' + esc(parsed.overview) + '</p>' : '') +
  '<div style="font-family:system-ui,Arial">' + body + '</div>' +
  '<p style="color:#999;font-size:12px">' + picks.length + ' picks from ' + items.length + ' recent articles across ' + Object.keys(groups).length + ' categories.</p>';
const subject = picks.length ? 'Brief: ' + picks.length + ' picks · ' + Object.keys(groups).map((c) => labels[c] || c).join(', ') : 'Brief: quiet news day';
return [{ json: { subject, html, count: picks.length } }];
